 void GetPath([Out,MarshalAs(UnmanagedType.LPWStr)]StringBuilder path,int size,IntPtr data,uint flags);void GetIDList(out IntPtr p);void SetIDList(IntPtr p);void GetDescription([Out,MarshalAs(UnmanagedType.LPWStr)]StringBuilder text,int size);void SetDescription([MarshalAs(UnmanagedType.LPWStr)]string text);void GetWorkingDirectory([Out,MarshalAs(UnmanagedType.LPWStr)]StringBuilder text,int size);void SetWorkingDirectory([MarshalAs(UnmanagedType.LPWStr)]string text);void GetArguments([Out,MarshalAs(UnmanagedType.LPWStr)]StringBuilder text,int size);void SetArguments([MarshalAs(UnmanagedType.LPWStr)]string text);void GetHotkey(out short key);void SetHotkey(short key);void GetShowCmd(out int command);void SetShowCmd(int command);void GetIconLocation([Out,MarshalAs(UnmanagedType.LPWStr)]StringBuilder text,int size,out int index);void SetIconLocation([MarshalAs(UnmanagedType.LPWStr)]string path,int index);void SetRelativePath([MarshalAs(UnmanagedType.LPWStr)]string path,uint reserved);void Resolve(IntPtr owner,uint flags);void SetPath([MarshalAs(UnmanagedType.LPWStr)]string path);
 }
 static Key AppKey {get{return new Key("9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3",5);}}
 internal static string Id(string normal){string test=Environment.GetEnvironmentVariable("JAGO_SHELL_TEST_ID");return test!=null&&test.StartsWith("Jago.Test.",StringComparison.Ordinal)?test+"."+normal.Substring(normal.LastIndexOf('.')+1):normal;}
 internal static string Identity(string file){object link=new Link();try{((IPersistFile)link).Load(file,0);var key=AppKey;Value value;((Properties)link).GetValue(ref key,out value);try{return value.type==31||value.type==8?Marshal.PtrToStringUni(value.pointer):null;}finally{PropVariantClear(ref value);}}finally{Marshal.FinalReleaseComObject(link);}}
 internal static bool Stamp(string file,string target,string id){object link=new Link();try{((IPersistFile)link).Load(file,2);var path=new StringBuilder(32768);((ShellLink)link).GetPath(path,path.Capacity,IntPtr.Zero,0);if(!String.Equals(Path.GetFullPath(path.ToString()),Path.GetFullPath(target),StringComparison.OrdinalIgnoreCase))return false;var key=AppKey;var value=new Value{type=31,pointer=Marshal.StringToCoTaskMemUni(id)};try{((Properties)link).SetValue(ref key,ref value);((Properties)link).Commit();((IPersistFile)link).Save(file,true);}finally{PropVariantClear(ref value);}SHChangeNotify(0x2000,5,file,IntPtr.Zero);return true;}finally{Marshal.FinalReleaseComObject(link);}}
 static List<string> Repair(string executable,string id){var changed=new List<string>();if(id.StartsWith("Jago.Test.",StringComparison.Ordinal))return changed;string roaming=Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);foreach(string folder in new[]{Path.Combine(roaming,"Microsoft","Windows","Start Menu","Programs","Jago Suite Preview"),Path.Combine(roaming,"Microsoft","Windows","Start Menu","Programs","Jago Suite"),Path.Combine(roaming,"Microsoft","Internet Explorer","Quick Launch","User Pinned","TaskBar")}){if(!Directory.Exists(folder))continue;foreach(string link in Directory.GetFiles(folder,id=="Jago.Capture"?"Jago Capture*.lnk":"Jago Board*.lnk"))try{if(Identity(link)!=id&&Stamp(link,executable,id))changed.Add(link);}catch{}}return changed;}
 internal static bool Register(string appId,string executable,Tuple<string,string>[] tasks,string report){var rejected=new List<string>();var accepted=new List<string>();var repaired=new List<string>();string error=null;string id=Id(appId);string reports=Environment.GetEnvironmentVariable("JAGO_SHELL_TEST_REPORT_ROOT");if(id.StartsWith("Jago.Test.",StringComparison.Ordinal)&&!String.IsNullOrEmpty(reports))report=Path.Combine(reports,appId.Substring(appId.LastIndexOf('.')+1)+".json");try{Marshal.ThrowExceptionForHR(SetCurrentProcessExplicitAppUserModelID(id));repaired=Repair(executable,id);var application=System.Windows.Application.Current??new System.Windows.Application();var list=new JumpList();list.JumpItemsRejected+=(s,e)=>{for(int i=0;i<e.RejectedItems.Count;i++){var task=e.RejectedItems[i] as JumpTask;rejected.Add((task==null?"Task":task.Title)+": "+e.RejectionReasons[i]);}};foreach(var task in tasks)list.JumpItems.Add(new JumpTask{Title=task.Item1,Arguments=task.Item2,ApplicationPath=executable,WorkingDirectory=Path.GetDirectoryName(executable),IconResourcePath=executable,IconResourceIndex=0,Description=task.Item1});JumpList.SetJumpList(application,list);accepted.AddRange(list.JumpItems.OfType<JumpTask>().Select(t=>t.Title));}catch(Exception e){error=e.ToString();}bool ok=error==null&&rejected.Count==0&&accepted.Count==tasks.Length;try{Directory.CreateDirectory(Path.GetDirectoryName(report));File.WriteAllText(report,new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{ok=ok,id=id,executable=executable,accepted=accepted,rejected=rejected,repaired=repaired,error=error}));}catch{}return ok;}
